static uint64_t causal_exposure(const QualityResult&r){uint64_t n=0;for(auto layer:r.report.at("pilot_exposure"))for(auto expert:layer)n+=expert.at(zones[0]).get<uint64_t>()+expert.at(zones[1]).get<uint64_t>();return n;}
static bool zero_causal_but_different(const QualityResult&B,const QualityResult&C){return causal_exposure(B)==0&&causal_exposure(C)==0&&(B.V!=C.V||B.logits.size()!=C.logits.size()||std::memcmp(B.logits.data(),C.logits.data(),size_t(511)*B.V*4)!=0);}
